const D = { mix:.7, energy:.5, zoom:.05, spin:.5, fade:.86, sat:70, hue:280, speed:1, style:'echo', act:'expand', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const W = width, H = height, dg = drawingContext;
const clamp = (v,a,b) => v < a ? a : v > b ? b : v;
const fr = i => { const s = Math.sin(i*127.1 + P.seed*311.7) * 43758.5453; return s - Math.floor(s); };
function style_is(s){ return P.style === s; }

const md = 480, sc = md / Math.max(W, H);
const bw = Math.max(2, Math.round(W*sc)), bh = Math.max(2, Math.round(H*sc));
const key = bw + 'x' + bh;
if (!S.a || S.key !== key || S.seedUsed !== P.seed) {
  S.a = createGraphics(bw, bh); S.b = createGraphics(bw, bh);
  S.a.colorMode(HSB,360,100,100,100); S.b.colorMode(HSB,360,100,100,100);
  S.a.clear(); S.b.clear();
  S.key = key; S.seedUsed = P.seed; S.pp = false;
}

const beatKick = clamp(K.pulse*.6 + A.bass*.8, 0, 1.4);
const inten = K.intensity==null ? .6 : K.intensity;
const en = clamp(P.energy, 0, 1.4);

let zdir = 1, spinMul = 1;
if (P.act === 'implode') zdir = -1;
else if (P.act === 'warp') { zdir = Math.sin(K.t*0.5) >= 0 ? 1 : -1; spinMul = 1.8; }
const z = 1 + zdir * clamp(P.zoom,0,0.22) * (0.5 + 0.6*beatKick + 0.3*inten) * P.speed;
const spin = P.spin * 0.045 * spinMul * P.speed * (0.6 + 0.7*beatKick + 0.4*Math.sin(K.t*0.31));
const fade = clamp(P.fade, 0.5, 0.965);
const inject = clamp(1 - fade + 0.04 + 0.10*beatKick, 0.02, 0.6);

let th = P.hue, ts = P.sat, tb = 100;
if (style_is('chroma')) { th = (P.hue + K.t*40) % 360; ts = 85; }
else if (style_is('ghost')) { ts = 6; tb = 100; }
else if (style_is('ink')) { ts = clamp(P.sat,30,80); tb = 74; }

const src = S.pp ? S.a : S.b, dst = S.pp ? S.b : S.a;
const bctx = dst.drawingContext;

dst.push();
dst.clear();
dst.translate(bw/2, bh/2);
dst.rotate(spin);
dst.scale(z);
dst.imageMode(CENTER);
dst.tint(th, ts, tb, fade*100);
dst.image(src, 0, 0);
if (style_is('kaleido')) { dst.scale(-1, 1); dst.image(src, 0, 0); }
dst.pop();

bctx.save();
bctx.globalCompositeOperation = 'source-over';
bctx.globalAlpha = inject;
try { bctx.drawImage(dg.canvas, 0, 0, bw, bh); } catch(e) {}
bctx.globalAlpha = 1;
bctx.restore();

// self-seed: drifting core dot + energy-scaled orbiting sparks + beat ring
dst.push();
dst.noStroke();
const dhu = style_is('ghost') ? 0 : (P.hue + 40) % 360;
const dsa = style_is('ghost') ? 0 : 80;
const dx = bw*(0.5 + 0.30*Math.cos(K.t*0.9 + fr(1)*6.28));
const dy = bh*(0.5 + 0.30*Math.sin(K.t*1.17 + fr(2)*6.28));
dst.fill(dhu, dsa, style_is('ink')?80:96, 60 + 30*beatKick);
dst.circle(dx, dy, bw*(0.02 + 0.12*en));
const sparks = Math.floor(2 + en*7);
for (let i=0;i<sparks;i++){
  const ph = fr(i*3+7)*6.28;
  const rr = bw*(0.10 + 0.24*fr(i*5+1));
  const sx = bw*0.5 + Math.cos(K.t*(0.5+0.6*fr(i)) + ph)*rr;
  const sy = bh*0.5 + Math.sin(K.t*(0.6+0.7*fr(i*2)) + ph)*rr;
  dst.fill(dhu, dsa, style_is('ink')?78:98, 35 + 45*en);
  dst.circle(sx, sy, bw*(0.008 + 0.03*en));
}
if (beatKick > 0.12) {
  dst.noFill();
  dst.stroke((P.hue + 180)%360, style_is('ghost')?0:70, 98, 55*beatKick);
  dst.strokeWeight(bw*0.008*(1 + beatKick));
  dst.circle(bw/2, bh/2, bw*(0.10 + 0.16*beatKick));
}
dst.pop();

blendMode(BLEND);
imageMode(CORNER);
dg.save();
dg.globalAlpha = clamp(P.mix, 0.15, 1);
image(dst, 0, 0, W, H);
dg.restore();

S.pp = !S.pp;
blendMode(BLEND);
dg.shadowBlur = 0;
